-- Payroll configuration (SCRUM-567, the company payroll's R2):
-- docs/progress/plans/payroll-real-build/PLAN.md §1, "0021 payroll_config".
--
-- Generated by drizzle-kit from shared/schema.ts, then hand-edited the way
-- 0018 is: every statement re-runnable (IF NOT EXISTS, keys added only where
-- missing by name), the public-schema qualifier stripped, and ordered so the composite parent
-- keys exist before the foreign keys that use them. Expand-only.
--
-- Every new table carries tenant_id (the park group). A child names its
-- parent through (tenant_id, parent_id) -> parent(tenant_id, id), so no row
-- can point at another park group's branch, operator, entity or account.
-- branches and operators get the unique (tenant_id, id) those keys need.
--
-- statutory_rule_sets gains rule_format: every existing row is 'legacy-v1'
-- (the old engine's), and the company engine's rows are 'company-v1', its
-- StatutoryRules stored as is. The old engine's reads filter to legacy-v1
-- (server/storage.ts), so neither engine sees the other's rows.
--
-- The Thai company-v1 rule set is seeded by seed_tenant_payroll_rule_sets,
-- defined here but RUN ONLY LAZILY by the app per park group on first use --
-- never by this migration: the restore rehearsal holds that migrations add
-- no rows to tables the old world already carries, and this one targets
-- and the app runs the same function for a park group made later. Nothing
-- else is seeded: no entity, account, branch detail, deduction list, revenue
-- stream or welfare fund setting (the welfare fund start date is entered by
-- an administrator, plan §8).
CREATE TABLE IF NOT EXISTS "payroll_paying_entities" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"name" text NOT NULL,
	"country" text NOT NULL,
	"tax_id" text,
	"sso_employer_number" text,
	"operator_id" uuid,
	"default_pay_day" integer DEFAULT 28 NOT NULL,
	"created_by" varchar,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"archived_at" timestamp with time zone,
	CONSTRAINT "payroll_paying_entities_country_check" CHECK ("payroll_paying_entities"."country" IN ('TH', 'MY')),
	CONSTRAINT "payroll_paying_entities_pay_day_check" CHECK ("payroll_paying_entities"."default_pay_day" BETWEEN 1 AND 31)
);
