-- The Thai company-v1 rule set for one park group, made only where the park
-- group has no company-wide Thai company-v1 row yet (so a later version an
-- administrator saved is never joined by a second starting row). Returns how
-- many rows it made. The rules are the prototype's defaultRules("TH",
-- "2025-01") (client/src/lib/payroll-prototype/seeds.ts:290-330) as the
-- plan's §4 lists them, with two owner rulings applied: no "Casual" role
-- keys and includeCasuals false (casual workers are outside this payroll,
-- 2026-10-20), and no fixed allowance (the template's transport amount is a
-- demonstration value; allowances are entered in setup, plan §8). Its "my"
-- block is the template's inert defaults, which the type requires.
CREATE OR REPLACE FUNCTION seed_tenant_payroll_rule_sets(p_tenant uuid) RETURNS integer LANGUAGE plpgsql AS $fn$
DECLARE
	v_made integer;
BEGIN
	IF NOT EXISTS (SELECT 1 FROM tenants WHERE id = p_tenant) THEN
		RETURN 0;
	END IF;
	INSERT INTO statutory_rule_sets
		(tenant_id, operator_id, branch_id, country_code, name, description, effective_from, effective_to, rules, status, rule_format)
	SELECT p_tenant, NULL, NULL, 'TH', 'Thailand payroll rules',
	       'Thai SSO, PIT, overtime and proration rules for the company payroll (the rulebook template).',
	       DATE '2025-01-01', NULL, $rules${
