		},
		"serviceCharge": {
			"taxable": true,
			"socialSecurity": true,
			"ewfWage": false,
			"ewfReason": "Service charge classification requires accountant confirmation."
		},
		"overtime": {
			"taxable": true,
			"socialSecurity": true,
			"ewfWage": false,
			"ewfReason": "Overtime is outside normal working hours."
		},
		"lunch": {
			"taxable": false,
			"socialSecurity": false,
			"ewfWage": false,
			"ewfReason": "Welfare/meal benefit is excluded in this illustration."
		},
		"paidLeave": {
			"taxable": true,
			"socialSecurity": true,
			"ewfWage": true,
			"ewfReason": "Paid leave is included as normal paid wages."
		},
		"holidayPay": {
			"taxable": true,
			"socialSecurity": true,
			"ewfWage": true,
			"ewfReason": "Paid holidays are included as normal paid wages."
		},
		"exitLeavePayout": {
			"taxable": true,
			"socialSecurity": false,
			"ewfWage": false,
			"ewfReason": "Unused-leave exit payout is a settlement; accountant review required."
		},
		"boothVoucher": {
			"taxable": true,
			"socialSecurity": false,
			"ewfWage": false,
			"ewfReason": "Booth vouchers require accountant confirmation."
		},
		"allowance:transport": {
			"taxable": true,
			"socialSecurity": true,
			"ewfWage": false,
			"ewfReason": "Transport/expense allowance is excluded unless confirmed as fixed fuel/position pay."
		}
	}
}$rules$::jsonb, 'active', 'company-v1'
	WHERE NOT EXISTS (
		SELECT 1 FROM statutory_rule_sets s
		 WHERE s.tenant_id = p_tenant AND s.country_code = 'TH' AND s.branch_id IS NULL AND s.rule_format = 'company-v1')
	ON CONFLICT DO NOTHING;
	GET DIAGNOSTICS v_made = ROW_COUNT;
	RETURN v_made;
END $fn$;
